import{_ as n,o,c as e,a3 as s,j as a}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"02 · 虚拟内存：让每个程序都以为自己独占一台机器","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/os/02.md","filePath":"bagu/os/02.md"}'),l={name:"bagu/os/02.md"};function r(i,t,p,c,d,h){return o(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="_02-·-虚拟内存-让每个程序都以为自己独占一台机器" tabindex="-1">02 · 虚拟内存：让每个程序都以为自己独占一台机器 <a class="header-anchor" href="#_02-·-虚拟内存-让每个程序都以为自己独占一台机器" aria-label="Permalink to &quot;02 · 虚拟内存：让每个程序都以为自己独占一台机器&quot;">​</a></h1><blockquote><p>这是 OS 模块里&quot;最反直觉&quot;的一篇。看懂它，你就能理解为什么程序会段错误、为什么内存能&quot;超卖&quot;、为什么数组比链表快。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>给每个进程发一套<strong>假的、连续的、从 0 开始的地址</strong>，由硬件+内核在背后翻译成真实的物理地址。</p><h2 id="生活类比-图书馆的索书号" tabindex="-1">生活类比：图书馆的索书号 <a class="header-anchor" href="#生活类比-图书馆的索书号" aria-label="Permalink to &quot;生活类比：图书馆的索书号&quot;">​</a></h2><ul><li><strong>虚拟地址</strong>：你在检索系统里看到的&quot;索书号 A-001&quot;。你只知道这个号，不知道书实际在几楼哪个架子。</li><li><strong>物理地址</strong>：书真正摆放的位置。</li><li><strong>页表</strong>：检索系统里的对照表（A-001 → 3 楼 7 排）。</li><li><strong>TLB</strong>：你手边的小纸条，记着刚才查过的几个号。查过的就不用再翻系统了。</li><li><strong>缺页中断</strong>：你要的书不在架上（在仓库），管理员去取。取的过程中你得等。</li><li><strong>换出（swap）</strong>：架子满了，把最久没人看的书搬回仓库。</li></ul><p>关键点：<strong>每个读者看到的索书号都从 A-001 开始，但实际对应的书完全不同</strong>。这就是进程隔离。</p><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、没有虚拟内存会怎样" tabindex="-1">一、没有虚拟内存会怎样 <a class="header-anchor" href="#一、没有虚拟内存会怎样" aria-label="Permalink to &quot;一、没有虚拟内存会怎样&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>没有虚拟内存：</span></span>
<span class="line"><span>  物理内存 0x0000 ------------------</span></span>
<span class="line"><span>            0x1000  [程序 A 的代码]</span></span>
<span class="line"><span>            0x2000  [程序 A 的数据]   &lt; A 认为自己从 0x1000 开始</span></span>
<span class="line"><span>            0x3000  [程序 B 的代码]   &lt; B 也认为自己从 0x1000 开始！</span></span>
<span class="line"><span>            0x4000  ...</span></span></code></pre></div><p>三个必然的灾难：</p><ol><li><strong>地址冲突</strong>：A 和 B 都往 <code>0x1000</code> 写，互相覆盖。</li><li><strong>无法隔离</strong>：A 的野指针能改掉 B 的数据，甚至改掉内核。</li><li><strong>必须连续</strong>：程序需要 100MB 连续内存，但物理内存碎片化，凑不出来 &gt; 明明总空闲 200MB 却分配失败。</li></ol><h3 id="二、加了虚拟内存之后" tabindex="-1">二、加了虚拟内存之后 <a class="header-anchor" href="#二、加了虚拟内存之后" aria-label="Permalink to &quot;二、加了虚拟内存之后&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  进程 A 的虚拟空间          物理内存              进程 B 的虚拟空间</span></span>
<span class="line"><span>  +--------------+      +--------------+      +--------------+</span></span>
<span class="line"><span>  | 0x0000 代码  |--+   | 0x0000 内核  |   +--| 0x0000 代码  |</span></span>
<span class="line"><span>  | 0x1000 数据  |--+--&gt;| 0x1000  A代码|&lt;--+--| 0x1000 数据  |</span></span>
<span class="line"><span>  | 0x2000 堆    |--+--&gt;| 0x2000  B数据|   |  | 0x2000 堆    |</span></span>
<span class="line"><span>  | ...          |  |   | 0x3000  A数据|&lt;--+  | ...          |</span></span>
<span class="line"><span>  | 0xFFFF 栈    |--+   | 0x4000 空闲  |      | 0xFFFF 栈    |</span></span>
<span class="line"><span>  +--------------+      +--------------+      +--------------+</span></span>
<span class="line"><span>      假地址                 真地址                 假地址</span></span></code></pre></div><p>三个灾难同时消失：</p><ol><li>两个进程的 <code>0x1000</code> 映射到不同物理页 &gt; 不冲突。</li><li>进程看不到别人的物理页 &gt; 隔离。</li><li>虚拟地址连续，物理页可以散落 &gt; 不需要连续物理内存。</li></ol><h3 id="三、地址翻译的完整路径" tabindex="-1">三、地址翻译的完整路径 <a class="header-anchor" href="#三、地址翻译的完整路径" aria-label="Permalink to &quot;三、地址翻译的完整路径&quot;">​</a></h3>`,17),a("figure",{class:"fig"},[a("span",{class:"fig-hint"},"← 左右滑动看完整图 →"),a("svg",{viewBox:"0 0 680 268",width:"100%",xmlns:"http://www.w3.org/2000/svg",role:"img","aria-label":"虚拟地址到物理地址的翻译过程"},[a("defs",null,[a("marker",{id:"arw-va",viewBox:"0 0 10 10",markerWidth:"9",markerHeight:"9",refX:"8.5",refY:"5",markerUnits:"userSpaceOnUse",orient:"auto"},[a("path",{d:"M2 1.5 L8 5 L2 8.5",class:"f-line",fill:"none","stroke-linecap":"round","stroke-linejoin":"round"})])]),a("text",{class:"f-label",x:"420",y:"20","text-anchor":"middle"},"TLB 命中：1 个周期，直接拿到页框号"),a("rect",{class:"f-box f-dash",x:"356",y:"28",width:"128",height:"44",rx:"8"}),a("text",{class:"f-title",x:"420",y:"56","text-anchor":"middle"},"② TLB 快表"),a("path",{class:"f-line f-dash",d:"M254 96 V50 H356","marker-end":"url(#arw-va)"}),a("path",{class:"f-line f-dash",d:"M484 50 H598 V96","marker-end":"url(#arw-va)"}),a("rect",{class:"f-box",x:"10",y:"96",width:"144",height:"62",rx:"8"}),a("text",{class:"f-title",x:"82",y:"122","text-anchor":"middle"},"虚拟地址"),a("text",{class:"f-mono",x:"82",y:"144","text-anchor":"middle"},"0x1234"),a("rect",{class:"f-box",x:"182",y:"96",width:"144",height:"62",rx:"8"}),a("text",{class:"f-title",x:"254",y:"122","text-anchor":"middle"},"① 页号 + 偏移"),a("text",{class:"f-mono",x:"254",y:"144","text-anchor":"middle"},"0x1 | 0x234"),a("rect",{class:"f-box-hi",x:"354",y:"96",width:"144",height:"62",rx:"8"}),a("text",{class:"f-title",x:"426",y:"122","text-anchor":"middle"},"③ 查页表"),a("text",{class:"f-mono",x:"426",y:"144","text-anchor":"middle"},"0x1 → 0x7A"),a("rect",{class:"f-box-alt",x:"526",y:"96",width:"144",height:"62",rx:"8"}),a("text",{class:"f-title",x:"598",y:"122","text-anchor":"middle"},"⑤ 物理地址"),a("text",{class:"f-mono",x:"598",y:"144","text-anchor":"middle"},"0x7A234"),a("path",{class:"f-line",d:"M154 127 H182","marker-end":"url(#arw-va)"}),a("path",{class:"f-line",d:"M326 127 H354","marker-end":"url(#arw-va)"}),a("path",{class:"f-line",d:"M498 127 H526","marker-end":"url(#arw-va)"}),a("text",{class:"f-label",x:"254",y:"182","text-anchor":"middle"},"页大小 4KB，低 12 位是页内偏移"),a("rect",{class:"f-box",x:"250",y:"196",width:"360",height:"56",rx:"8"}),a("text",{class:"f-title",x:"430",y:"219","text-anchor":"middle"},"④ 缺页中断（内核处理）"),a("text",{class:"f-label",x:"430",y:"241","text-anchor":"middle"},"分配页框 · 脏页写回 · 读盘 · 改页表 · 重执行指令"),a("path",{class:"f-line",d:"M426 158 V196","marker-end":"url(#arw-va)"}),a("text",{class:"f-label",x:"436",y:"180"},"存在位=0")]),a("figcaption",{class:"fig-cap"},"拆地址、查 TLB、走页表都是 MMU 在硬件里干的，纳秒级；只有「存在位=0」才掉进内核的缺页处理，那一步要读盘，慢 6 个数量级。同一次翻译里，快慢的分界线就画在 ③ 和缺页之间。")],-1),s(`<p><strong>关键理解</strong>：第 ④ 步是<strong>内核在替硬件干活</strong>，而 ②③ 是<strong>硬件（MMU）在干</strong>。这个分工是&quot;快慢&quot;的根源：命中 TLB 是纳秒级，缺页要读磁盘是毫秒级——<strong>差 6 个数量级</strong>。</p><h3 id="四、为什么要多级页表" tabindex="-1">四、为什么要多级页表 <a class="header-anchor" href="#四、为什么要多级页表" aria-label="Permalink to &quot;四、为什么要多级页表&quot;">​</a></h3><p>假设 32 位地址、4KB 页：虚拟地址空间有 2^20 个页，每个页表项 4 字节 &gt; <strong>一张页表要 4MB</strong>。</p><p>每个进程一张 4MB 页表？100 个进程就是 400MB，全用来存&quot;这个地址不存在&quot;了。而且大部分地址根本没用过。</p><p>多级页表解决方式：<strong>按需分配</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一级页表（1024 项，4KB）</span></span>
<span class="line"><span>  +- 项 0   &gt; 指向一个二级页表（4KB）</span></span>
<span class="line"><span>  +- 项 1   &gt; 空（这个范围没用到，不分配）</span></span>
<span class="line"><span>  +- 项 2   &gt; 空</span></span>
<span class="line"><span>  +- ...</span></span></code></pre></div><p>进程实际只用了几个区域（代码、堆、栈），所以只需要分配几条路径上的页表。<strong>总占用从固定 4MB 降到几 KB</strong>。</p><p>代价：<strong>多了一次访存</strong>（查 4 级就是 4 次访存）。这就是 TLB 存在的理由——缓存住翻译结果，把 4 次访存压回 1 次。</p><h3 id="五、页面置换算法" tabindex="-1">五、页面置换算法 <a class="header-anchor" href="#五、页面置换算法" aria-label="Permalink to &quot;五、页面置换算法&quot;">​</a></h3><p>内存满了要选一个页换出，选谁？</p><table tabindex="0"><thead><tr><th>算法</th><th>怎么选</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td><strong>OPT</strong></td><td>换出&quot;未来最久不用&quot;的</td><td>理论最优</td><td>无法实现（要预知未来），只作基准</td></tr><tr><td><strong>FIFO</strong></td><td>换出最早进来的</td><td>简单</td><td>有 Belady 异常（页框变多，缺页反而变多）</td></tr><tr><td><strong>LRU</strong></td><td>换出最久没访问的</td><td>效果好</td><td>精确实现太贵（要每次访存都记时间戳）</td></tr><tr><td><strong>Clock（近似 LRU）</strong></td><td>环形扫描，访问位=1 就跳过并清零，遇到 0 就换出</td><td>便宜，效果好</td><td>是近似</td></tr></tbody></table><p><strong>实际系统用 Clock（也叫 NRU）</strong>。原因：LRU 需要硬件支持或每次访存都更新链表，成本不可接受；Clock 只需要一个访问位（硬件自动置 1），扫一圈就能近似&quot;最近没用过&quot;。</p><h3 id="六、抖动-thrashing" tabindex="-1">六、抖动（Thrashing） <a class="header-anchor" href="#六、抖动-thrashing" aria-label="Permalink to &quot;六、抖动（Thrashing）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>进程太多 &gt; 每个进程分到的页框太少 &gt; 频繁缺页 &gt; 频繁换入换出</span></span>
<span class="line"><span>   &gt; CPU 大部分时间在等磁盘 &gt; CPU 利用率看起来很低</span></span>
<span class="line"><span>   &gt; 操作系统误以为&quot;负载不够&quot;，再加进程 &gt; 更糟 &gt; 死循环</span></span></code></pre></div><p><strong>解法</strong>：工作集模型——统计每个进程最近用到的页集合，如果所有工作集之和超过物理内存，就<strong>挂起一些进程</strong>（降低多道程度），而不是继续换页。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果没有虚拟内存" tabindex="-1">反事实 1：如果没有虚拟内存 <a class="header-anchor" href="#反事实-1-如果没有虚拟内存" aria-label="Permalink to &quot;反事实 1：如果没有虚拟内存&quot;">​</a></h3><p>三个灾难（地址冲突、无法隔离、必须连续）会同时出现。而且<strong>程序必须在编译时就知道自己会加载到哪个地址</strong>，这对动态链接库是致命的——两个程序都链接同一个 libc，它该放在哪？</p><h3 id="反事实-2-如果没有-tlb" tabindex="-1">反事实 2：如果没有 TLB <a class="header-anchor" href="#反事实-2-如果没有-tlb" aria-label="Permalink to &quot;反事实 2：如果没有 TLB&quot;">​</a></h3><p>每次访存都要查 4 级页表 = 4 次额外访存。程序的实际速度会降到 1/5。TLB 命中率通常在 99% 以上，这是虚拟内存&quot;看起来不慢&quot;的唯一原因。</p><h3 id="反事实-3-如果页太大-太小" tabindex="-1">反事实 3：如果页太大 / 太小 <a class="header-anchor" href="#反事实-3-如果页太大-太小" aria-label="Permalink to &quot;反事实 3：如果页太大 / 太小&quot;">​</a></h3><ul><li><strong>页太大（比如 1MB）</strong>：内部碎片严重。一个只要 1KB 的程序也要占 1MB；换页时一次搬 1MB，慢。</li><li><strong>页太小（比如 512B）</strong>：页表项数量爆炸，页表本身占的内存和访存次数都上去了。</li><li>4KB 是权衡出来的经验值（x86 还支持 2MB/1GB 的大页，用于数据库、JVM 这类需要大内存连续映射的场景）。</li></ul><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：什么是虚拟内存？</strong></p><blockquote><p>三层递进答：① 每个进程有独立的虚拟地址空间，从 0 开始；② 虚拟地址通过页表映射到物理地址；③ 映射关系可以指向&quot;不在内存里的页&quot;，访问时触发缺页，由内核按需从磁盘载入。 <strong>核心价值是三个</strong>：隔离、超卖（虚拟总量可以超过物理内存）、免连续。</p></blockquote><p><strong>Q：缺页中断的完整流程？</strong></p><blockquote><p>按上面第 ④ 步列的五步答，别只说&quot;从磁盘读进来&quot;。要提到<strong>脏页要先写回</strong>、<strong>更新页表后要重新执行那条指令</strong>。</p></blockquote><p><strong>Q：为什么数组比链表快？（这题表面考数据结构，实际考这里）</strong></p><blockquote><p>三个原因，越往后越硬： ① 数组内存连续，<strong>一条缓存行能装多个元素</strong>，一次加载多次命中；链表节点散落，每次跳转都可能缓存未命中。 ② 数组支持<strong>硬件预取</strong>（CPU 检测到顺序访问会提前加载），链表是随机跳转，预取器无能为力。 ③ 数组不需要额外指针，同样数据量占用更少内存，缓存能装下更多有效数据。</p></blockquote><p><strong>Q：malloc 分配的内存是物理内存吗？</strong></p><blockquote><p>不是。<code>malloc</code> 只是从堆区划一段<strong>虚拟地址</strong>给你（小内存走 <code>brk</code>，大内存走 <code>mmap</code>），<strong>并没有分配物理页</strong>。真正的物理页在你第一次写入时通过缺页中断才分配——这叫<strong>按需调页</strong>。 所以 <code>malloc(1GB)</code> 能立刻返回，但真去写这 1GB 时才会变慢甚至 OOM。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>虚拟内存是什么？</span></span>
<span class="line"><span>  &gt; 页表存在哪？（内存里，MMU 从 CR3 找到基址）</span></span>
<span class="line"><span>    &gt; 页表太大怎么办？（多级页表，按需分配）</span></span>
<span class="line"><span>      &gt; 多级页表多了访存怎么办？（TLB）</span></span>
<span class="line"><span>        &gt; TLB 未命中 + 页不在内存呢？（缺页中断，走磁盘）</span></span>
<span class="line"><span>          &gt; 内存满了换谁？（Clock 近似 LRU）</span></span>
<span class="line"><span>            &gt; 换得太频繁呢？（抖动 &gt; 挂起进程，降多道程度）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/01">进程与线程：谁在跑，跑的时候带着什么</a>：进程隔离就是靠&quot;每个进程一套页表&quot;实现的</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/dsa/01">复杂度与数组、链表</a>：缓存局部性、数组快于链表的根本原因</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/os/04">IO 模型与零拷贝：等设备的时候，CPU 在干什么</a>：<code>mmap</code> 把文件映射进地址空间，是零拷贝的基础</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/01">索引与 B+ 树</a>：B+ 树一个节点设计成一页（16KB），就是为了让一次磁盘 IO 读到一个完整节点</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/02">事务与 ACID</a>：<code>fsync</code> 强制刷盘，本质是&quot;别让页缓存的延迟骗了持久性&quot;</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：<code>malloc(1GB)</code> 为什么能瞬间返回？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为它只分配了<strong>虚拟地址空间</strong>，没有分配物理内存。</p><p>大块内存（通常 &gt;128KB）走 <code>mmap</code>，内核只在页表里登记&quot;这段虚拟地址有效&quot;，物理页一个都没给。等程序真正写入某个页时，触发缺页中断，内核才分配一个物理页。</p><p>这叫<strong>按需调页（demand paging）</strong>。好处是：申请了但没用的内存不占实际资源；坏处是：程序可能在写入时才突然变慢或被 OOM Killer 杀掉。</p></details><p><strong>Q2：为什么说&quot;程序里的指针值是虚拟地址&quot;？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为你 <code>printf(&quot;%p&quot;, ptr)</code> 打出来的，就是虚拟地址。</p><p>同一个程序跑两次，同一个变量打印出来的地址通常是一样的（因为虚拟地址空间布局固定，有 ASLR 也只是随机化基址），但<strong>对应的物理地址每次都可能不同</strong>。</p><p>这也解释了为什么&quot;把指针值存到文件里，下次运行再用&quot;是错的——虚拟地址只在当次进程内有效。</p></details><p><strong>Q3：页面置换为什么不用 LRU，而用 Clock？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为<strong>精确 LRU 太贵</strong>。</p><p>精确 LRU 需要每次访存都更新&quot;最近访问时间&quot;，要么在硬件里加时间戳（贵），要么每次访存都陷入内核改链表（不可接受，一次访存变几微秒）。</p><p>Clock 只需要一个<strong>访问位</strong>：硬件在访存时自动置 1，内核换页时环形扫一遍，遇到 1 就清零跳过，遇到 0 就换出。开销极低，效果接近 LRU。</p><p>这是典型的工程取舍：<strong>用 95% 的效果换 1% 的成本</strong>。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;索书号&quot;类比会让人以为映射是一对一的</strong>。实际上多个虚拟页可以映射到同一个物理页（共享内存），一个虚拟页也可以暂时没有映射（未分配）。</li><li><strong>&quot;每个进程从 0 开始&quot;不严谨</strong>。32 位 Linux 用户空间是 <code>0x0 ~ 0xBFFFFFFF</code>，内核占高地址 <code>0xC0000000</code> 以上，所有进程共享这部分内核映射。</li><li><strong>缺页 ≠ 错误</strong>。缺页是正常机制（按需调页），只有访问非法地址（页表项无效且不属于任何合法区域）才是<strong>段错误</strong>。</li><li><strong>swap 不等于虚拟内存</strong>。虚拟内存是地址翻译机制，swap 只是&quot;物理内存不够时的后备存储&quot;。没有 swap 也能有虚拟内存。</li><li><strong>多级页表的层数</strong>：32 位通常 2 级，64 位通常 4 级（x86-64），不是&quot;级数越多越好&quot;。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能说出虚拟内存解决的<strong>三个</strong>具体问题（隔离 / 超卖 / 免连续），每个配一个&quot;不这么做会出的事故&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能画出虚拟地址 &gt; TLB &gt; 页表 &gt; 物理地址的完整翻译路径，标出哪几步是硬件、哪几步是内核</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能完整背出缺页中断的 5 个处理步骤（含&quot;脏页先写回&quot;和&quot;重新执行指令&quot;）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能解释多级页表为什么能省内存，以及它带来的代价和补偿手段</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说清 Clock 算法为什么能替代 LRU（要说出&quot;访问位&quot;和&quot;成本&quot;）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能解释 <code>malloc(1GB)</code> 为什么瞬间返回</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,46)])])}const x=n(l,[["render",r]]);export{u as __pageData,x as default};
